import sys

def find_pairs(n, k):
    if k == 0:
        # If k is 0, we can simply pair each number with its complement (n-1-i)
        return [(i, n-1-i) for i in range(n//2)]

    # Try to find pairs such that the bitwise AND of each pair is k
    pairs = []
    used = [False] * n

    for i in range(n):
        if used[i]:
            continue
        for j in range(i+1, n):
            if not used[j] and (i & j) == k:
                pairs.append((i, j))
                used[i] = True
                used[j] = True
                break

    if len(pairs) == n // 2:
        return pairs
    else:
        return None

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        k = int(data[index])
        index += 1

        pairs = find_pairs(n, k)
        if pairs is None:
            results.append("-1")
        else:
            results.append("\n".join(f"{a} {b}" for a, b in pairs))

    print("\n".join(results))

if __name__ == "__main__":
    main()
